// Flödets filter: åtta taggar som kryssrutor, Gäst, Team och Band på luminusloom.net.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const s = fs.readFileSync('public/index.html', 'utf8');
const k = {};
for (const t of ['arbete', 'musik', 'mat', 'aktivitet', 'grupp', 'resa', 'hemma', 'bild']) k['tagg_' + t] = s.includes(`['${t}',`);
k.gast_kryss = s.includes('id="fgast"') && s.includes('<span>Gäst</span>');
k.team_select = s.includes('id="fteam"') && s.includes('Alla team');
k.band_select = s.includes('id="fband"') && ['Husbandet', 'Karavanen', 'Leonid', 'Ek & Lin'].every((b) => s.includes(`'${b}'`));
k.fieldset_legend = /<fieldset class="ftaggar"><legend/.test(s);
k.rensa = s.includes('id="frensa"');
k.nya_inlagg_taggas = s.includes('doc.taggar=raknaTaggar(doc)');
k.databasens_taggar_forst = s.includes('Array.isArray(x.taggar)?x.taggar:raknaTaggar(x)');
k.ok = Object.values(k).every(Boolean);
console.log(JSON.stringify(k));
process.exit(k.ok ? 0 : 1);
